let attractors = [];
let numAttractors = 5;
let quadtreeWidth = 1400;
let quadtreeHeight = 850;
let maxSeedsLimit = 75;
let pSeeds = []; // Persistent seeds for smooth cellular physics

class Attractor {
  constructor(i) {
    this.i = i;
    this.x = 0;
    this.y = 0;
  }
  update() {
    let time = frameCount * 0.005;
    this.x = map(noise(this.i * 12 + time, 150), 0, 1, -quadtreeWidth / 2, quadtreeWidth / 2);
    this.y = map(noise(this.i * 12 + time, 550), 0, 1, -quadtreeHeight / 2, quadtreeHeight / 2);
  }
}

class QTNode {
  constructor(x, y, w, h, level) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.level = level;
    this.children = [];
    this.isLeaf = true;
  }

  subdivide(maxL) {
    let subdiv = false;
    if (this.level < maxL) {
      let cx = this.x + this.w / 2;
      let cy = this.y + this.h / 2;
      let sensitivity = 1.3 + (window.audioLow || 0.5) * 1.8;
      for (let a of attractors) {
        let d = dist(cx, cy, a.x, a.y);
        if (d < (this.w * sensitivity)) {
          subdiv = true;
          break;
        }
      }
    }

    if (subdiv) {
      this.isLeaf = false;
      let hw = this.w / 2;
      let hh = this.h / 2;
      this.children.push(new QTNode(this.x, this.y, hw, hh, this.level + 1));
      this.children.push(new QTNode(this.x + hw, this.y, hw, hh, this.level + 1));
      this.children.push(new QTNode(this.x, this.y + hh, hw, hh, this.level + 1));
      this.children.push(new QTNode(this.x + hw, this.y + hh, hw, hh, this.level + 1));
      for (let child of this.children) {
        child.subdivide(maxL);
      }
    }
  }

  collectSeeds(list) {
    if (list.length >= maxSeedsLimit) return;
    if (this.isLeaf) {
      list.push(createVector(this.x + this.w / 2, this.y + this.h / 2));
    } else {
      for (let child of this.children) {
        child.collectSeeds(list);
      }
    }
  }
}

function clipPolygon(poly, m, d) {
  let clipped = [];
  if (poly.length === 0) return clipped;
  for (let i = 0; i < poly.length; i++) {
    let current = poly[i];
    let next = poly[(i + 1) % poly.length];
    let currIn = p5.Vector.sub(current, m).dot(d) <= 0;
    let nextIn = p5.Vector.sub(next, m).dot(d) <= 0;
    if (currIn) {
      clipped.push(current);
    }
    if (currIn !== nextIn) {
      let diff = p5.Vector.sub(next, current);
      let denom = diff.dot(d);
      if (abs(denom) > 0.0001) {
        let t = p5.Vector.sub(m, current).dot(d) / denom;
        let intersect = p5.Vector.add(current, p5.Vector.mult(diff, t));
        clipped.push(intersect);
      }
    }
  }
  return clipped;
}

function setup() {
  createCanvas(1280, 720, WEBGL);
  for (let i = 0; i < numAttractors; i++) {
    attractors.push(new Attractor(i));
  }
  background(0);
}

function draw() {
  background(10, 10, 12);

  for (let a of attractors) {
    a.update();
  }

  let beatEnergy = window.beatEnergy || 0.0;
  let maxLevel = (beatEnergy > 0.66) ? 5 : 4;

  let root = new QTNode(-quadtreeWidth/2, -quadtreeHeight/2, quadtreeWidth, quadtreeHeight, 0);
  root.subdivide(maxLevel);

  let qtSeeds = [];
  root.collectSeeds(qtSeeds);

  // 變種特點: 自底層物理更新 Persistent Seeds (有機胞腔分裂與排斥力)
  updateOrganicSeeds(qtSeeds, beatEnergy);

  let time = frameCount * 0.0035;
  let camRotX = sin(time * 0.6) * 0.22;
  let camRotY = cos(time * 0.5) * 0.32;
  let camZoom = 1.05 + (window.audioLow || 0.5) * 0.1 + beatEnergy * 0.2;
  let storyboardScale = (window.storyboardWeight !== undefined) ? (window.storyboardWeight / 50.0) : 1.0;

  push();
  scale(camZoom * storyboardScale);
  rotateX(camRotX);
  rotateY(camRotY);

  let lightDir = createVector(0.3, 0.45, 0.83).normalize();

  // 繪製 Voronoi 胞腔
  for (let i = 0; i < pSeeds.length; i++) {
    let s = pSeeds[i];
    let cellPoly = [
      createVector(-quadtreeWidth * 0.7, -quadtreeHeight * 0.7),
      createVector(quadtreeWidth * 0.7, -quadtreeHeight * 0.7),
      createVector(quadtreeWidth * 0.7, quadtreeHeight * 0.7),
      createVector(-quadtreeWidth * 0.7, quadtreeHeight * 0.7)
    ];

    let neighbors = [];
    for (let j = 0; j < pSeeds.length; j++) {
      if (i === j) continue;
      let dSq = sq(pSeeds[i].x - pSeeds[j].x) + sq(pSeeds[i].y - pSeeds[j].y);
      neighbors.push({ idx: j, d2: dSq });
    }
    neighbors.sort((a, b) => a.d2 - b.d2);

    let clipCount = min(neighbors.length, 10);
    for (let n = 0; n < clipCount; n++) {
      let neighborSeed = pSeeds[neighbors[n].idx];
      let m = p5.Vector.add(s, neighborSeed).mult(0.5);
      let d = p5.Vector.sub(neighborSeed, s);
      cellPoly = clipPolygon(cellPoly, m, d);
      if (cellPoly.length < 3) break;
    }

    if (cellPoly.length < 3) continue;

    let baseZ = -90;
    let apexZ = baseZ + (noise(s.x * 0.003, s.y * 0.003, frameCount * 0.005) - 0.45) * 200 + beatEnergy * 130 * sin(frameCount * 0.04 + i);
    let apex = createVector(s.x, s.y, apexZ);

    let styleIdx = i % 3;
    colorMode(RGB, 255, 255, 255, 1.0);

    if (styleIdx === 0) {
      // 變種特點: 實心半透明灰白色胞體
      for (let v = 0; v < cellPoly.length; v++) {
        let pCurrent = cellPoly[v];
        let pNext = cellPoly[(v + 1) % cellPoly.length];

        let vA = apex;
        let vB = createVector(pCurrent.x, pCurrent.y, baseZ);
        let vC = createVector(pNext.x, pNext.y, baseZ);

        let edge1 = p5.Vector.sub(vB, vA);
        let edge2 = p5.Vector.sub(vC, vA);
        let normal = edge1.cross(edge2).normalize();

        let dotProd = normal.dot(lightDir);
        let brightness = map(abs(dotProd), 0, 1, 100, 235);

        fill(brightness, brightness * 0.98, brightness * 0.95, 0.45); // 暖黃半透明灰
        stroke(20, 20, 25, 0.6);
        strokeWeight(0.8);

        beginShape(TRIANGLES);
        vertex(vA.x, vA.y, vA.z);
        vertex(vB.x, vB.y, vB.z);
        vertex(vC.x, vC.y, vC.z);
        endShape();
      }
    } else {
      // 變種特點: 精緻的雙線描邊線框結構
      stroke(220, 220, 230, 0.52);
      strokeWeight(0.6);
      noFill();

      // 底面多邊形
      beginShape();
      for (let pt of cellPoly) vertex(pt.x, pt.y, baseZ);
      endShape(CLOSE);

      // 側邊稜線
      for (let pt of cellPoly) {
        line(apex.x, apex.y, apex.z, pt.x, pt.y, baseZ);
      }

      // 內縮雙線
      push();
      stroke(220, 220, 230, 0.25);
      strokeWeight(0.4);
      beginShape();
      for (let pt of cellPoly) {
        let innerPt = p5.Vector.lerp(pt, s, 0.08);
        vertex(innerPt.x, innerPt.y, baseZ);
      }
      endShape(CLOSE);
      for (let pt of cellPoly) {
        let innerPt = p5.Vector.lerp(pt, s, 0.08);
        line(apex.x, apex.y, apex.z - 10, innerPt.x, innerPt.y, baseZ);
      }
      pop();
    }
  }
  pop();
}

function updateOrganicSeeds(qtSeeds, beatEnergy) {
  // 1. 初始化
  if (pSeeds.length === 0) {
    for (let qs of qtSeeds) {
      pSeeds.push(createVector(qs.x, qs.y));
    }
    return;
  }

  // 2. 對應四叉樹目標引力
  for (let ps of pSeeds) {
    let bestTarget = null;
    let bestD = Infinity;
    for (let qs of qtSeeds) {
      let d = dist(ps.x, ps.y, qs.x, qs.y);
      if (d < bestD) {
        bestD = d;
        bestTarget = qs;
      }
    }
    if (bestTarget) {
      // 平滑拉向目標點
      ps.x = lerp(ps.x, bestTarget.x, 0.12);
      ps.y = lerp(ps.y, bestTarget.y, 0.12);
    }
  }

  // 3. 胞體排斥力 (防止重疊)
  for (let i = 0; i < pSeeds.length; i++) {
    for (let j = i + 1; j < pSeeds.length; j++) {
      let ps1 = pSeeds[i];
      let ps2 = pSeeds[j];
      let d = dist(ps1.x, ps1.y, ps2.x, ps2.y);
      let minDist = 45.0;
      if (d < minDist && d > 0.01) {
        let force = p5.Vector.sub(ps1, ps2).normalize().mult((minDist - d) * 0.25);
        ps1.add(force);
        ps2.sub(force);
      }
    }
  }

  // 4. 重拍時隨機分裂胞腔 (Mitosis)
  if (beatEnergy > 0.68 && pSeeds.length < maxSeedsLimit && random(1.0) < 0.28) {
    let splitIdx = int(random(pSeeds.length));
    let parent = pSeeds[splitIdx];
    let offset = p5.Vector.random2D().mult(10.0);
    pSeeds.push(createVector(parent.x + offset.x, parent.y + offset.y));
    parent.sub(offset);
  }

  // 5. 超出上限時合併胞腔
  if (pSeeds.length > maxSeedsLimit) {
    pSeeds.splice(0, pSeeds.length - maxSeedsLimit);
  }
}

